-- Adds eight verified Tbilisi hospitals to emergency_hospitals.
-- Coordinates cross-checked against OpenStreetMap / Nominatim; phone numbers
-- confirmed against OSM tags or the hospital's own listing (July 2026).
-- Idempotent: re-running refreshes the rows instead of failing on the primary key.

on conflict (id) do update set name_en=excluded.name_en, address=excluded.address, phone=excluded.phone, lat=excluded.lat, lng=excluded.lng, notes_en=excluded.notes_en, notes_ka=excluded.notes_ka, notes_ru=excluded.notes_ru;

-- The same hospitals as map pins, so the "Hospitals" layer matches the
-- Emergency screen. MediClubGeorgia is not open_24h: it is an international
-- clinic with daytime hours, not a round-the-clock emergency hospital.
on conflict (id) do update set name=excluded.name, type=excluded.type, address=excluded.address, lat=excluded.lat, lng=excluded.lng, open_24h=excluded.open_24h;
